<style>
.wheat-wrap{max-width:1450px;margin:22px auto;padding:0 15px 40px;color:#243247}.wheat-top{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:22px;flex-wrap:wrap}.wheat-top h2{font-size:25px;font-weight:750;margin:0}.wheat-muted{color:#718096;font-size:13px}.wheat-card{background:#fff;border:1px solid #e4e9f0;border-radius:14px;box-shadow:0 5px 20px rgba(29,43,68,.045);padding:22px;margin-bottom:18px}.wheat-card h4{font-size:16px;font-weight:700;margin:0 0 18px}.wheat-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.wheat-field label{font-weight:650;font-size:13px;display:block;margin-bottom:7px}.wheat-field input,.wheat-field select,.wheat-field textarea{display:block;width:100%;min-height:43px;padding:10px 12px;border:1px solid #dce3eb;border-radius:9px;background:#fff;color:#243247}.wheat-field textarea{min-height:90px}.wheat-actions{display:flex;gap:8px;flex-wrap:wrap}.wheat-btn{display:inline-flex;align-items:center;justify-content:center;gap:6px;padding:10px 16px;border:0;border-radius:8px;background:#234c83;color:white!important;text-decoration:none!important;font-size:13px;font-weight:650;cursor:pointer}.wheat-btn.light{background:#eff3f8;color:#234c83!important}.wheat-btn.danger{background:#fff1f2;color:#be123c!important}.wheat-btn.small{padding:6px 9px;font-size:12px}.wheat-table-wrap{overflow-x:auto}.wheat-table{border-collapse:collapse;width:100%;font-size:13px;white-space:nowrap}.wheat-table th{background:#243a57;color:#fff;padding:12px 10px;text-align:left}.wheat-table td{padding:11px 10px;border-bottom:1px solid #edf1f5}.wheat-table tbody tr:hover{background:#f7faff}.wheat-kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:18px}.wheat-kpi{padding:19px;background:#fff;border:1px solid #e4e9f0;border-radius:12px}.wheat-kpi b{display:block;font-size:22px;margin-top:6px}.wheat-filter{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;align-items:end}.wheat-filter .wheat-field input{min-height:40px}.wheat-error{font-size:12px;color:#c53030;margin-top:5px}.wheat-alert{padding:12px 15px;border-radius:9px;margin-bottom:15px;background:#e9f8ef;color:#17613c}.wheat-invalid{background:#fff4e8;color:#9b4a00}.wheat-print-title{text-align:center;margin:0 0 20px}.wheat-print-title h2,.wheat-print-title h3{margin:2px}.wheat-right{text-align:right}.wheat-full{grid-column:1/-1}@media(max-width:850px){.wheat-kpis,.wheat-filter{grid-template-columns:repeat(2,1fr)}}@media(max-width:560px){.wheat-grid,.wheat-kpis,.wheat-filter{grid-template-columns:1fr}}@media print{body{background:white!important}.main-menu,.header-navbar,.navbar,.wheat-no-print,aside,nav{display:none!important}.wheat-wrap{max-width:none;margin:0;padding:0}.wheat-card{border:0;box-shadow:none;padding:0}.wheat-table{font-size:10px}.wheat-table th,.wheat-table td{padding:5px;border:1px solid #ccc}.wheat-table th{background:#eee!important;color:#111!important;-webkit-print-color-adjust:exact;print-color-adjust:exact}@page{size:A4 landscape;margin:10mm}}
</style>